using System;
using System.IO;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.Build.Reporting;
using UnityEngine.Rendering;
namespace Deepsea.Editor {
 public static class CoastFineShoreBuild {
  const string Root="Assets/Deepsea/Resources/CoastFineShore/",Source="Assets/Deepsea/ThirdParty/CoastArtV20/";
  [Serializable]class Record{public string name,material;public Vector3[] vertices,normals;public Vector2[] uv;public Color[] colors;public int[] triangles;}
  [Serializable]class Archive{public Record[] meshes;public int triangles;}
  [Serializable]class TreeArchive{public Record[] meshes;public Vector3 anchor0;public float treeLiftY;}
  static void SaveMesh(string name,Mesh mesh){var path=Root+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null)AssetDatabase.CreateAsset(mesh,path);else{EditorUtility.CopySerialized(mesh,old);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);}}
  static Material SaveMaterial(string name,Material from,Shader shader){if(from==null)throw new Exception("Missing source material for "+name);var path=Root+name+".mat";var result=AssetDatabase.LoadAssetAtPath<Material>(path);if(result==null){result=new Material(from);AssetDatabase.CreateAsset(result,path);}else result.CopyPropertiesFromMaterial(from);result.shader=shader;EditorUtility.SetDirty(result);return result;}
  static Mesh ImportMesh(Record rec){if(rec.vertices==null||rec.vertices.Length<3||rec.triangles==null||rec.triangles.Length%3!=0)throw new Exception("Malformed mesh "+rec.name);if(rec.normals==null||rec.normals.Length!=rec.vertices.Length||rec.uv==null||rec.uv.Length!=rec.vertices.Length)throw new Exception("Missing split normals/UV "+rec.name);var mesh=new Mesh{name=rec.name,indexFormat=IndexFormat.UInt32};mesh.vertices=rec.vertices;mesh.normals=rec.normals;mesh.uv=rec.uv;if(rec.colors!=null&&rec.colors.Length==rec.vertices.Length)mesh.colors=rec.colors;mesh.triangles=rec.triangles;mesh.RecalculateTangents();mesh.RecalculateBounds();SaveMesh(rec.name,mesh);return AssetDatabase.LoadAssetAtPath<Mesh>(Root+rec.name+".asset");}
  static Transform Find(Transform root,string name){foreach(var t in root.GetComponentsInChildren<Transform>(true))if(t.name==name)return t;return null;}
  static Texture2D Map(string name){var result=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"FineShore_"+name+".png");if(result==null)throw new Exception("Missing baked map "+name);return result;}
  static void IncludeShader(Shader shader){if(shader==null)throw new Exception("Required v20 shader missing");var settings=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/GraphicsSettings.asset")[0]);var list=settings.FindProperty("m_AlwaysIncludedShaders");for(int i=0;i<list.arraySize;i++)if(list.GetArrayElementAtIndex(i).objectReferenceValue==shader)return;list.InsertArrayElementAtIndex(list.arraySize);list.GetArrayElementAtIndex(list.arraySize-1).objectReferenceValue=shader;settings.ApplyModifiedPropertiesWithoutUndo();}
  [MenuItem("深海灯塔/美术样板/构建岸岩精修v20")]
  public static void Build(){
   Directory.CreateDirectory(Root);foreach(var file in Directory.GetFiles(Source,"FineShore_*.png"))File.Copy(file,Root+Path.GetFileName(file),true);AssetDatabase.Refresh();
   foreach(var file in Directory.GetFiles(Root,"FineShore_*.png")){var importer=AssetImporter.GetAtPath(file) as TextureImporter;if(importer==null)throw new Exception("Texture import failed "+file);bool normal=file.Contains("_normal"),linear=normal||file.Contains("_roughness")||file.Contains("_ao");importer.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;importer.sRGBTexture=!linear;importer.wrapMode=TextureWrapMode.Clamp;importer.alphaSource=TextureImporterAlphaSource.None;importer.mipmapEnabled=true;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=8;importer.maxTextureSize=2048;importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.SaveAndReimport();}
   var data=JsonUtility.FromJson<Archive>(File.ReadAllText(Source+"FineShore.json"));var contact=JsonUtility.FromJson<TreeArchive>(File.ReadAllText(Source+"TreeContact.json"));if(data.meshes==null||data.meshes.Length==0)throw new Exception("Empty shoreline archive");
   var scene=EditorSceneManager.OpenScene("Assets/Deepsea/Scenes/CoastArtMaple.unity",OpenSceneMode.Single);var env=GameObject.Find("EN_MistCapeShowcase");if(env==null)throw new Exception("Authored v19 scene missing");if(PrefabUtility.IsPartOfPrefabInstance(env))PrefabUtility.UnpackPrefabInstance(env,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
   // Freeze the actual authored v19 environment before changing any local geometry or material.
   PrefabUtility.SaveAsPrefabAsset(env,Root+"Baseline.prefab");var leaves=env.GetComponent<CoastMapleLeaves>();if(leaves==null||leaves.anchors==null||leaves.anchors.Length==0)throw new Exception("v19 leaf anchors missing");var baselineAnchors=(Vector3[])leaves.anchors.Clone();
   var fineShader=Shader.Find("Deepsea/CoastFineStone");var waterShader=Shader.Find("Deepsea/CoastSunGlintStudy");if(fineShader==null||waterShader==null)throw new Exception("v20 shaders missing");
   var stone=AssetDatabase.LoadAssetAtPath<Material>(Root+"FineStone.mat");if(stone==null){stone=new Material(fineShader);AssetDatabase.CreateAsset(stone,Root+"FineStone.mat");}stone.shader=fineShader;stone.enableInstancing=true;stone.SetColor("_BaseColor",new Color(.80f,.82f,.82f,1));stone.SetFloat("_NormalStrength",1);stone.SetTexture("_BaseMap",Map("basecolor"));stone.SetTexture("_BumpMap",Map("normal"));stone.SetTexture("_AOMap",Map("ao"));stone.SetTexture("_RoughnessMap",Map("roughness"));stone.SetTexture("_CausticMap",Resources.Load<Texture2D>("CoastMaterials/CausticLight"));EditorUtility.SetDirty(stone);
   foreach(var name in new[]{"EN_MapleHeadland03_LOD0","EN_MapleFoot03_LOD0"}){var target=Find(env.transform,name);if(target==null)throw new Exception("Replacement target missing: "+name);UnityEngine.Object.DestroyImmediate(target.gameObject);}
   int vertices=0,triangles=0;var section=new GameObject("EN_FineShoreSection");section.transform.SetParent(env.transform,false);var lod0=new List<Renderer>();var lod1=new List<Renderer>();
   foreach(var rec in data.meshes){var mesh=ImportMesh(rec);vertices+=mesh.vertexCount;triangles+=mesh.triangles.Length/3;var go=new GameObject(rec.name);go.transform.SetParent(section.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=stone;if(rec.name.Contains("LOD1"))lod1.Add(renderer);else lod0.Add(renderer);}
   if(lod0.Count==0)throw new Exception("LOD0 mesh missing");if(lod1.Count>0){var group=section.AddComponent<LODGroup>();group.SetLODs(new[]{new LOD(.13f,lod0.ToArray()),new LOD(0,lod1.ToArray())});group.RecalculateBounds();}
   if(contact.meshes==null||contact.meshes.Length!=2)throw new Exception("Expected Tree00 Bark and Leaves only");foreach(var rec in contact.meshes){if(rec.name!="EN_RedMaple00_Bark_LOD0"&&rec.name!="EN_RedMaple00_Leaves_LOD0")throw new Exception("Tree contact changed unexpected object "+rec.name);var target=Find(env.transform,rec.name);if(target==null)throw new Exception("Tree target missing "+rec.name);target.GetComponent<MeshFilter>().sharedMesh=ImportMesh(rec);}
   leaves.anchors[0]=contact.anchor0;EditorUtility.SetDirty(leaves);
   var water=Find(env.transform,"ShowcaseWater");if(water==null)throw new Exception("Authored water missing");var wr=water.GetComponent<MeshRenderer>();var original=SaveMaterial("WaterOriginal",wr.sharedMaterial,wr.sharedMaterial.shader);var study=SaveMaterial("WaterStudy",original,waterShader);study.SetFloat("_GlintEnable",1);study.SetFloat("_GlintIntensity",2.4f);study.SetFloat("_GlintScale",8);study.SetFloat("_GlintRoughness",.52f);study.SetFloat("_GlintDensity",.9f);study.SetFloat("_GlintCoverage",.25f);study.SetFloat("_GlintSpeed",.6f);wr.sharedMaterial=study;
   foreach(var root in scene.GetRootGameObjects()){var old=root.GetComponent<CoastMapleRuntime>();if(old!=null){UnityEngine.Object.DestroyImmediate(old);var runtime=root.AddComponent<CoastFineShoreRuntime>();runtime.baselineAnchors=baselineAnchors;}}
   IncludeShader(fineShader);IncludeShader(waterShader);const string path="Assets/Deepsea/Scenes/CoastArtFineShore.unity";EditorSceneManager.SaveScene(scene,path);AssetDatabase.SaveAssets();Directory.CreateDirectory("Builds/CoastArtV20");
   var oldName=PlayerSettings.productName;var oldPipeline=GraphicsSettings.renderPipelineAsset;var oldQuality=QualitySettings.renderPipeline;BuildReport report;
   try{PlayerSettings.productName="深海灯塔 · 岸岩精修 v20";var pipeline=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>("Assets/Deepsea/Resources/CoastRefinement/SamplePipeline.asset");GraphicsSettings.renderPipelineAsset=pipeline;QualitySettings.renderPipeline=pipeline;report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{path},locationPathName="Builds/CoastArtV20/MistCape-FineShore.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});}
   finally{PlayerSettings.productName=oldName;GraphicsSettings.renderPipelineAsset=oldPipeline;QualitySettings.renderPipeline=oldQuality;AssetDatabase.SaveAssets();}
   if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Fine shoreline build failed");Directory.CreateDirectory("Verification/coast-art-v20-build");File.WriteAllText("Verification/coast-art-v20-build/mesh-summary.json","{\"localArchiveTrianglesIncludingLOD1\":"+triangles+",\"localArchiveVerticesIncludingLOD1\":"+vertices+",\"treeLiftY\":"+contact.treeLiftY.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"replacedOriginalRockObjects\":2,\"sourceVersion\":19}");CoastFineShoreAudit.Run();Debug.Log("COAST_FINE_SHORE_BUILD_OK");
  }
 }
}
